import{_ as a,o as r,c as i,ag as t}from"./chunks/framework.D7Pdja0E.js";const u=JSON.parse('{"title":"Google Drive 모듈 — 워크허브 ↔ 드라이브 통합","description":"","frontmatter":{},"headers":[],"relativePath":"02-user-guide/gdrive-module.md","filePath":"02-user-guide/gdrive-module.md","lastUpdated":1780579853000}'),o={name:"02-user-guide/gdrive-module.md"};function l(n,e,s,d,p,h){return r(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="google-drive-모듈-—-워크허브-↔-드라이브-통합" tabindex="-1">Google Drive 모듈 — 워크허브 ↔ 드라이브 통합 <a class="header-anchor" href="#google-drive-모듈-—-워크허브-↔-드라이브-통합" aria-label="Permalink to &quot;Google Drive 모듈 — 워크허브 ↔ 드라이브 통합&quot;">​</a></h1><p>워크허브의 모든 첨부 / 파일 / 명함 / 미팅 트랜스크립트를 <strong>Google Drive 원본</strong>으로 다룰 수 있게 해주는 모듈입니다. 워크허브가 파일을 자기 스토리지에 복사하지 않고, <strong>Drive 의 webViewLink 와 권한</strong>으로 직접 연결합니다.</p><blockquote><p><strong>왜 Drive 인가</strong>: 회사가 이미 Workspace 를 쓰고 있으면 파일을 두 곳에 복제하지 않고 원본 한 곳에서 관리할 수 있습니다. 권한·검색·버전관리·외부 공유가 모두 Drive 기준.</p></blockquote><hr><h2 id="_1-동작-그림" tabindex="-1">1. 동작 그림 <a class="header-anchor" href="#_1-동작-그림" aria-label="Permalink to &quot;1. 동작 그림&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>   워크허브 화면                           Google Drive</span></span>
<span class="line"><span>   ─────────────                          ──────────────</span></span>
<span class="line"><span>   메시지/태스크/명함/미팅</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        │ ① &quot;Drive 첨부&quot; 클릭</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>   Google Picker 팝업  ◀─── 본인 Drive 마이/공유 드라이브</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        │ ② 파일 선택</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>   워크허브 첨부 행 생성 ─────▶ external_id = drive_file_id</span></span>
<span class="line"><span>        │                       (워크허브 안에 파일 본체 복사 X)</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        │ ③ 수신자에게 자동 권한 부여 (선택 — grant_on_send=true)</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>   gdrive_grants 테이블 ──────▶ Drive permissions API</span></span>
<span class="line"><span>                                 (수신자가 &quot;구글에서 열기&quot; 클릭 시 열림)</span></span></code></pre></div><p>핵심:</p><ul><li>워크허브 DB 에는 <strong>파일 본체가 들어가지 않음</strong> — Drive ID + 미리보기 메타만</li><li>&quot;구글에서 열기&quot; 클릭 시 워크허브 백엔드가 Drive <code>webViewLink</code> 로 302 redirect</li><li>메시지 삭제 / 멤버 변동 시 Drive 권한도 자동 회수</li></ul><hr><h2 id="_2-사전-준비" tabindex="-1">2. 사전 준비 <a class="header-anchor" href="#_2-사전-준비" aria-label="Permalink to &quot;2. 사전 준비&quot;">​</a></h2><blockquote><p>기관관리자가 먼저 <strong>Google 모듈 + Drive 모듈</strong> 을 활성화하고 Picker API Key 를 등록해야 합니다 — <a href="./../04-org-admin-guide/modules-gdrive.html">기관관리자 가이드 — Drive 모듈</a> 참고.</p></blockquote><p>활성화가 끝나면 메시지 첨부 / CRM 명함 인박스 / 미팅 트랜스크립트 등의 진입점이 노출됩니다.</p><h3 id="본인-사용자-—-한-번만" tabindex="-1">본인 사용자 — 한 번만 <a class="header-anchor" href="#본인-사용자-—-한-번만" aria-label="Permalink to &quot;본인 사용자 — 한 번만&quot;">​</a></h3><p>기관관리자가 Drive 모듈을 활성한 후, 본인이 처음 Drive 첨부를 누르면:</p><ol><li><strong>&quot;Google 계정 연결&quot;</strong> 안내 팝업 → 클릭</li><li>Google 동의 화면에서 본인 Gmail 계정 선택 + <strong>&quot;드라이브 파일 보기/관리&quot;</strong> 권한 동의</li><li>워크허브에 본인 OAuth 토큰 (AES-GCM 암호화) 저장 → 이후 모든 Drive 흐름이 본인 계정 권한으로 동작</li></ol><blockquote><p><strong>본인 계정 vs 공용 계정</strong>: 공유 드라이브를 쓰면 본인 계정이 공유 드라이브 멤버여야 첨부 가능. 마이드라이브 모드면 본인 드라이브 안의 파일만 접근.</p></blockquote><hr><h2 id="_3-메시지-dm-토픽-—-drive-파일-첨부" tabindex="-1">3. 메시지 / DM / 토픽 — Drive 파일 첨부 <a class="header-anchor" href="#_3-메시지-dm-토픽-—-drive-파일-첨부" aria-label="Permalink to &quot;3. 메시지 / DM / 토픽 — Drive 파일 첨부&quot;">​</a></h2><h3 id="_3-1-첨부하기" tabindex="-1">3.1 첨부하기 <a class="header-anchor" href="#_3-1-첨부하기" aria-label="Permalink to &quot;3.1 첨부하기&quot;">​</a></h3><p>메시지 입력창 우하단 <strong>📎 Drive</strong> 버튼 클릭:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌──────────────────────────────────────────────┐</span></span>
<span class="line"><span>│  Google Picker (Google 가 제공하는 표준 팝업)  │</span></span>
<span class="line"><span>│  ┌──────────────┬─────────────────────────┐  │</span></span>
<span class="line"><span>│  │ 📁 내 드라이브 │ 📁 공유 드라이브        │  │</span></span>
<span class="line"><span>│  └──────────────┴─────────────────────────┘  │</span></span>
<span class="line"><span>│  최근 파일 / 검색 / 폴더 탐색                  │</span></span>
<span class="line"><span>└──────────────────────────────────────────────┘</span></span></code></pre></div><ul><li><strong>내 드라이브</strong> 탭: 본인 마이드라이브</li><li><strong>공유 드라이브</strong> 탭: 본인이 멤버인 공유 드라이브들</li><li><strong>업로드</strong> 탭: 로컬 파일을 Drive 의 이 채널 폴더 (자동 생성됨) 로 즉시 업로드 후 첨부</li></ul><p>파일 선택 → 워크허브 메시지에 칩으로 표시:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>📄 견적서_2026Q2.xlsx [구글에서 열기]</span></span></code></pre></div><h3 id="_3-2-수신자-입장에서" tabindex="-1">3.2 수신자 입장에서 <a class="header-anchor" href="#_3-2-수신자-입장에서" aria-label="Permalink to &quot;3.2 수신자 입장에서&quot;">​</a></h3><p>수신자가 칩의 <strong>[구글에서 열기]</strong> 클릭 시:</p><ul><li>백엔드 <code>/files/{id}/open</code> 가 호출됨</li><li>워크허브가 본인 (작성자) Drive 권한을 자동 부여 (<code>grant_on_send=ON</code> 인 경우)</li><li>302 redirect 로 Drive <code>webViewLink</code> 이동</li><li>Drive 에서 본인 권한으로 열림</li></ul><h3 id="_3-3-자동-권한-회수" tabindex="-1">3.3 자동 권한 회수 <a class="header-anchor" href="#_3-3-자동-권한-회수" aria-label="Permalink to &quot;3.3 자동 권한 회수&quot;">​</a></h3><p>다음 이벤트 시 워크허브가 부여한 Drive 권한을 자동 해제:</p><table tabindex="0"><thead><tr><th>이벤트</th><th>회수 동작</th></tr></thead><tbody><tr><td>메시지/DM 삭제</td><td>해당 첨부의 모든 grantee 권한 회수</td></tr><tr><td>채널/프로젝트에서 멤버 제외</td><td>그 멤버의 모든 첨부 권한 일괄 회수</td></tr><tr><td>사용자 비활성화 (퇴사)</td><td>해당 사용자가 받은 모든 권한 회수</td></tr></tbody></table><p>→ <code>gdrive_grants</code> 테이블에 audit 기록 + Drive permissions API delete 호출.</p><blockquote><p><strong>본인이 직접 부여한 권한은 회수 안됨</strong>: 본인이 Drive 콘솔에서 직접 &quot;공유&quot; 한 권한은 워크허브가 만지지 않습니다. 워크허브가 자동 부여한 것만 추적.</p></blockquote><hr><h2 id="_4-crm-—-drive-인박스-트랜스크립트" tabindex="-1">4. CRM — Drive 인박스 / 트랜스크립트 <a class="header-anchor" href="#_4-crm-—-drive-인박스-트랜스크립트" aria-label="Permalink to &quot;4. CRM — Drive 인박스 / 트랜스크립트&quot;">​</a></h2><h3 id="_4-1-명함-—-drive-인박스-자동-ocr" tabindex="-1">4.1 명함 — Drive 인박스 (자동 OCR) <a class="header-anchor" href="#_4-1-명함-—-drive-인박스-자동-ocr" aria-label="Permalink to &quot;4.1 명함 — Drive 인박스 (자동 OCR)&quot;">​</a></h3><p>기관관리자가 모듈관리 → CRM 설정에서 <strong>명함 Drive 폴더</strong> 를 설정해두면:</p><ol><li>본인이 폰으로 명함 사진을 찍어 그 Drive 폴더에 업로드 (Drive 앱 / Workspace 동기화 등)</li><li>워크허브 <strong>고객관리 → 명함</strong> 화면에 <strong>Drive 인박스</strong> 영역에 자동으로 나타남</li><li><strong>[OCR 처리]</strong> 클릭 → Gemini Vision 으로 명함 자동 인식</li><li><strong>[확정]</strong> → 워크허브 명함 행 생성 + Drive 원본은 폴더 이동 + 파일명에 고객사명 자동 prefix</li></ol><p>이 흐름의 장점:</p><ul><li>폰 카메라 → Drive 업로드 → 워크허브 인식 → 고객 등록 = 한 동선</li><li>원본 명함 사진은 Drive 에 영구 보관 (워크허브가 카피하지 않음)</li><li>여러 사용자가 같은 폴더에 업로드하면 자동으로 인박스 공유</li></ul><h3 id="_4-2-미팅-트랜스크립트-—-drive-가져오기" tabindex="-1">4.2 미팅 트랜스크립트 — Drive 가져오기 <a class="header-anchor" href="#_4-2-미팅-트랜스크립트-—-drive-가져오기" aria-label="Permalink to &quot;4.2 미팅 트랜스크립트 — Drive 가져오기&quot;">​</a></h3><p>회의 녹음을 Otter/Plaud 같은 도구로 트랜스크립트 (.txt/.md/.srt/.vtt) 만들어 Drive 에 저장한 후:</p><ol><li>워크허브 <strong>고객관리 → 미팅 → [트랜스크립트로 자동 생성]</strong></li><li><strong>[Drive 에서 가져오기]</strong> 클릭 → Google Picker → 텍스트 파일 선택</li><li>백엔드가 1MB 까지 텍스트 가져옴 + LLM 으로 요약 + 미팅 행 자동 생성</li></ol><blockquote><p><strong>Drive 모듈 비활성 기관</strong>: 위 버튼이 <strong>[파일에서 가져오기]</strong> (로컬 업로드) 로 자동 전환.</p></blockquote><h3 id="_4-3-미팅-첨부" tabindex="-1">4.3 미팅 첨부 <a class="header-anchor" href="#_4-3-미팅-첨부" aria-label="Permalink to &quot;4.3 미팅 첨부&quot;">​</a></h3><p>미팅 행에서 [첨부] → Drive Picker → 녹음 원본 / 회의 자료 등 첨부. 메시지 첨부와 동일하게 Drive 권한 자동 부여 / 회수.</p><hr><h2 id="_5-gmail-첨부-→-drive-저장" tabindex="-1">5. Gmail 첨부 → Drive 저장 <a class="header-anchor" href="#_5-gmail-첨부-→-drive-저장" aria-label="Permalink to &quot;5. Gmail 첨부 → Drive 저장&quot;">​</a></h2><p>Gmail 모듈에서 받은 메일의 첨부 (영수증 / 견적서 / 인보이스 등) 를 Drive 로 영구 보관:</p><ol><li>메일 본문 우상단 <strong>[첨부 보기]</strong></li><li>첨부 행 우측 <strong>[Drive 로 저장]</strong> (명시적 동의 — 자동 import 금지)</li><li>워크허브 미리 정의된 Drive 폴더 (<code>/Workhub/Gmail-imports/</code>) 에 저장</li><li>저장 후: <ul><li>워크허브 첨부 행 생성 → 메일에서 역참조</li><li>경비 생성 시 receipt 로 자동 연결 가능 (<code>create_expense_from_email</code>)</li></ul></li></ol><blockquote><p><strong>본인 명시 동의가 필요</strong>: 워크허브가 받은편지함 자동 스캔하면서 첨부를 Drive 로 옮기지 않습니다. 사용자가 그 메일에서 직접 누른 경우에만.</p></blockquote><hr><h2 id="_6-파일-탭-—-drive-출처-메시징" tabindex="-1">6. 파일 탭 — Drive 출처 메시징 <a class="header-anchor" href="#_6-파일-탭-—-drive-출처-메시징" aria-label="Permalink to &quot;6. 파일 탭 — Drive 출처 메시징&quot;">​</a></h2><p>채널/토픽/프로젝트의 <strong>파일</strong> 탭은 모든 첨부를 통합 표시합니다.</p><table tabindex="0"><thead><tr><th>컬럼</th><th>표시</th></tr></thead><tbody><tr><td><strong>출처 배지</strong></td><td>🟢 <strong>Drive</strong> / ⚪ <strong>워크허브 업로드</strong></td></tr><tr><td><strong>이름</strong></td><td>클릭 시 미리보기 (Drive 파일은 webViewLink)</td></tr><tr><td><strong>소유자</strong></td><td>Drive 파일은 Drive 의 원본 소유자, 아니면 업로드 사용자</td></tr><tr><td><strong>액션</strong></td><td>🔗 구글에서 열기 / ⬇ 다운로드 / 🗑 삭제</td></tr></tbody></table><p>→ 워크허브 안에서 일관된 파일 관리 흐름. Drive 원본의 권한·소유는 그대로 유지.</p><hr><h2 id="_7-faq" tabindex="-1">7. FAQ <a class="header-anchor" href="#_7-faq" aria-label="Permalink to &quot;7. FAQ&quot;">​</a></h2><h3 id="q-공유-드라이브-안-쓰고-본인-마이드라이브로만-운영해도-되나요" tabindex="-1">Q. 공유 드라이브 안 쓰고 본인 마이드라이브로만 운영해도 되나요? <a class="header-anchor" href="#q-공유-드라이브-안-쓰고-본인-마이드라이브로만-운영해도-되나요" aria-label="Permalink to &quot;Q. 공유 드라이브 안 쓰고 본인 마이드라이브로만 운영해도 되나요?&quot;">​</a></h3><p>가능합니다. 단점:</p><ul><li>본인이 퇴사하면 본인 드라이브 자료가 사라짐 (회사가 백업할 수 없음)</li><li>같은 채널의 다른 사람이 본인 드라이브 파일을 보려면 grant 가 필요 (Drive 모듈이 자동 처리하지만)</li></ul><p>회사 자료의 영속성/공유성을 위해 <strong>공유 드라이브 권장</strong> — 기관관리자가 모듈 설정에서 지정.</p><h3 id="q-drive-콘솔에서-직접-권한-추가하면-워크허브에-영향이-있나요" tabindex="-1">Q. Drive 콘솔에서 직접 권한 추가하면 워크허브에 영향이 있나요? <a class="header-anchor" href="#q-drive-콘솔에서-직접-권한-추가하면-워크허브에-영향이-있나요" aria-label="Permalink to &quot;Q. Drive 콘솔에서 직접 권한 추가하면 워크허브에 영향이 있나요?&quot;">​</a></h3><p>영향 없음. 워크허브는 <strong>본인이 자동 부여한 권한만 추적</strong> (<code>gdrive_grants</code> 테이블). Drive 콘솔에서 직접 부여한 권한은 회수 대상이 아니고, 그대로 유지됩니다.</p><h3 id="q-파일-첨부-한도가-있나요" tabindex="-1">Q. 파일 첨부 한도가 있나요? <a class="header-anchor" href="#q-파일-첨부-한도가-있나요" aria-label="Permalink to &quot;Q. 파일 첨부 한도가 있나요?&quot;">​</a></h3><p>Drive 첨부는 파일 본체를 워크허브가 보관하지 않으므로 <strong>워크허브 스토리지 한도와 무관</strong>. Drive 자체 한도 (Workspace 플랜에 따른 GB) 만 적용.</p><h3 id="q-모바일-flutter-앱에서도-drive-첨부-되나요" tabindex="-1">Q. 모바일 (Flutter) 앱에서도 Drive 첨부 되나요? <a class="header-anchor" href="#q-모바일-flutter-앱에서도-drive-첨부-되나요" aria-label="Permalink to &quot;Q. 모바일 (Flutter) 앱에서도 Drive 첨부 되나요?&quot;">​</a></h3><p>현재 Drive Picker 는 <strong>웹 화면 전용</strong>. 모바일에서는 카메라/갤러리 → 일반 업로드만. 단:</p><ul><li>Drive 모바일 앱에서 파일을 워크허브 첨부로 공유는 가능 (운영체제의 &quot;공유&quot; 메뉴)</li><li>CRM 명함 인박스 흐름은 폰 카메라 → Drive 앱 업로드 → 워크허브 자동 인식으로 사실상 모바일 지원</li></ul><h3 id="q-본인이-drive-권한-회수했는데-워크허브-화면에는-칩이-남아있어요" tabindex="-1">Q. 본인이 Drive 권한 회수했는데 워크허브 화면에는 칩이 남아있어요. <a class="header-anchor" href="#q-본인이-drive-권한-회수했는데-워크허브-화면에는-칩이-남아있어요" aria-label="Permalink to &quot;Q. 본인이 Drive 권한 회수했는데 워크허브 화면에는 칩이 남아있어요.&quot;">​</a></h3><p>워크허브가 알지 못함 (Drive 측 외부 변경은 watch 하지 않음). 클릭 시 Drive 가 403 → 워크허브가 &quot;권한 없음&quot; 안내. 시각적 정리는 별도 cron 으로 검토 예정 (현재는 즉시 반영 안됨).</p><h3 id="q-공유-드라이브-멤버가-아닌-사람이-첨부-클릭하면" tabindex="-1">Q. 공유 드라이브 멤버가 아닌 사람이 첨부 클릭하면? <a class="header-anchor" href="#q-공유-드라이브-멤버가-아닌-사람이-첨부-클릭하면" aria-label="Permalink to &quot;Q. 공유 드라이브 멤버가 아닌 사람이 첨부 클릭하면?&quot;">​</a></h3><ul><li><code>grant_on_send=ON</code> 인 경우: 워크허브가 자동으로 read 권한 부여 → 열림</li><li><code>grant_on_send=OFF</code> 인 경우: Drive 가 &quot;접근 권한 없음&quot; → 사용자가 본인 Drive 콘솔에서 요청 필요</li></ul><h3 id="q-drive-모듈을-켰는데-메시지에-drive-버튼이-안-보여요" tabindex="-1">Q. Drive 모듈을 켰는데 메시지에 Drive 버튼이 안 보여요. <a class="header-anchor" href="#q-drive-모듈을-켰는데-메시지에-drive-버튼이-안-보여요" aria-label="Permalink to &quot;Q. Drive 모듈을 켰는데 메시지에 Drive 버튼이 안 보여요.&quot;">​</a></h3><p>체크:</p><ol><li>기관관리자가 <strong>Drive 모듈</strong> 을 실제로 ON 했는지 (<code>/app/admin/modules</code>)</li><li>본인이 Drive OAuth 연결을 했는지 (메시지 첨부 화면에 &quot;Google 계정 연결&quot; 안내가 떴어야 함)</li><li>기관관리자가 <strong>Google Picker API Key</strong> 를 입력했는지 — 없으면 Picker 가 안 뜸</li></ol><hr><h2 id="_8-트러블슈팅" tabindex="-1">8. 트러블슈팅 <a class="header-anchor" href="#_8-트러블슈팅" aria-label="Permalink to &quot;8. 트러블슈팅&quot;">​</a></h2><h3 id="본인-google-계정-권한-만료" tabindex="-1">&quot;본인 Google 계정 권한 만료&quot; <a class="header-anchor" href="#본인-google-계정-권한-만료" aria-label="Permalink to &quot;&quot;본인 Google 계정 권한 만료&quot;&quot;">​</a></h3><p>본인이 <a href="https://myaccount.google.com/permissions" target="_blank" rel="noreferrer">https://myaccount.google.com/permissions</a> 에서 워크허브 권한을 회수했거나 토큰이 만료된 경우. 워크허브에서 다시 Drive 첨부 클릭 시 자동으로 재연결 안내.</p><h3 id="drive-첨부-후-칩이-빨갛게-표시됨" tabindex="-1">&quot;Drive 첨부 후 칩이 빨갛게 표시됨&quot; <a class="header-anchor" href="#drive-첨부-후-칩이-빨갛게-표시됨" aria-label="Permalink to &quot;&quot;Drive 첨부 후 칩이 빨갛게 표시됨&quot;&quot;">​</a></h3><p><code>gdrive_grants</code> 의 상태가 <code>error</code> — Drive permissions API 호출 실패. 원인:</p><ul><li>본인이 그 파일의 소유자가 아니라 권한 부여 못함 (공유 드라이브 사용 권장)</li><li>Drive 측 quota 초과</li><li>파일이 이미 삭제됨</li></ul><p>칩 클릭 시 에러 메시지 노출. 본인 Drive 콘솔에서 직접 권한 부여로 우회 가능.</p><h3 id="공유-드라이브의-파일인데-워크허브-첨부-시-본인-권한이-회수되더라" tabindex="-1">&quot;공유 드라이브의 파일인데 워크허브 첨부 시 본인 권한이 회수되더라&quot; <a class="header-anchor" href="#공유-드라이브의-파일인데-워크허브-첨부-시-본인-권한이-회수되더라" aria-label="Permalink to &quot;&quot;공유 드라이브의 파일인데 워크허브 첨부 시 본인 권한이 회수되더라&quot;&quot;">​</a></h3><p>워크허브는 본인이 자동 부여한 grant 만 회수합니다. 본인이 공유 드라이브 멤버 자격으로 갖고 있던 원래 권한은 절대 회수 안 함. 회수 대상이 아닌데 그렇게 보이면 우연한 다른 원인.</p><hr><h2 id="_9-보안-개인정보" tabindex="-1">9. 보안 / 개인정보 <a class="header-anchor" href="#_9-보안-개인정보" aria-label="Permalink to &quot;9. 보안 / 개인정보&quot;">​</a></h2><ul><li><strong>OAuth refresh token</strong> 은 AES-GCM 으로 암호화돼 DB 저장 — 시스템관리자도 평문 조회 불가</li><li>워크허브는 본인 Drive 파일을 <strong>복사하지 않음</strong> — Drive ID 와 미리보기 메타만 보관</li><li>워크허브가 부여한 권한은 <strong>모두 <code>gdrive_grants</code> 에 audit 기록</strong> — 누가 / 언제 / 어떤 파일 / 누구에게</li><li>본인이 언제든 <a href="https://myaccount.google.com/permissions" target="_blank" rel="noreferrer">https://myaccount.google.com/permissions</a> 에서 워크허브 권한 회수 → 즉시 sync 중단</li><li>권한 회수 시 워크허브가 부여한 grant 도 자동 정리 (다음 호출에서 403 → 상태 갱신)</li></ul><hr><h2 id="관련-가이드" tabindex="-1">관련 가이드 <a class="header-anchor" href="#관련-가이드" aria-label="Permalink to &quot;관련 가이드&quot;">​</a></h2><ul><li><a href="./gmail-module.html">Gmail 모듈</a> — 메일 첨부를 Drive 로 저장</li><li><a href="./messaging.html">메시지</a> — 채널/토픽 메시징 (Drive 첨부 포함)</li><li><a href="./files.html">파일</a> — 파일 탭 일반 사용법</li><li><a href="./claude-mcp-integration.html">Claude / MCP 클라이언트 연결</a> — Claude 에서 Drive 첨부 자동화</li><li><a href="./../04-org-admin-guide/modules-gdrive.html">기관관리자 가이드 — Drive 모듈</a> — 모듈 활성화 / Picker API Key / 공유 드라이브</li></ul>`,91)])])}const g=a(o,[["render",l]]);export{u as __pageData,g as default};
